import {renderCommunityHero} from './community-hero-v7.js';
import {renderMela} from './mela.js';
import {renderRickshawStage} from './rickshaw-stage.js';
import {renderCultureTrail} from './culture-v3.js';
import {renderReelSections} from './reels.js';

/** People first; the painted rickshaw welcomes visitors to the mela further down. */
export function renderRickshawHome(ctx,tx){
 const {store,esc,icon,money}=ctx,s=store.getState();
 const events=s.events.filter(e=>e.status==='published').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);
 const members=s.members.filter(m=>m.directoryVisible&&m.status==='approved').slice(0,3);
 const posts=(s.posts||[]).filter(p=>p.status==='published').sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,3);
 const gallery=s.gallery.filter(g=>/art/i.test(g.category||'')||/^assets\/.*\.svg$/i.test(g.image||'')||/^assets\/(reference-|rickshaw-|folk-|bangladesh-japan-|mela-)/.test(g.image||'')).slice(0,3),firstEvent=events[0];
 const more=(en,bn)=>`${tx(en,bn)} ${icon('arrowUp')}`;
 const initials=name=>esc(String(name||'').split(' ').filter(Boolean).map(n=>n[0]).slice(0,2).join(''));
 const postCategory={introduction:'A new hello',question:'A little help',moment:'A shared moment'};
 const dateParts=e=>{const d=new Date(e.date+'T12:00:00');return {month:d.toLocaleDateString('en-US',{month:'short'}),day:d.getDate()};};
 const previewNote=posts[0];
 return `<div class="rk-home ch-home">
 ${renderCommunityHero(ctx,tx)}
 <nav class="ch-section-nav" aria-label="Explore homepage sections"><span>${tx('MAKE YOURSELF AT HOME','আপন মনে ঘুরে দেখুন')}</span><div><button type="button" data-home-jump="home-people">01 <b>Our people</b></button><button type="button" data-home-jump="community-wall">02 <b>The adda</b></button><button type="button" data-home-jump="home-gatherings">03 <b>Gatherings</b></button><button type="button" data-home-jump="home-reels">04 <b>Reels & stories</b></button><button type="button" data-home-jump="home-mela">05 <b>The mela</b></button></div><button class="rk-motion-toggle" data-motion-toggle type="button" aria-pressed="false"><span aria-hidden="true">Ⅱ</span><span data-motion-label>Pause motion</span></button></nav>
 <section class="ch-section ch-people" id="home-people" tabindex="-1" aria-labelledby="ch-people-title"><header class="ch-section-heading" data-reveal><div><p class="ch-eyebrow">01 / ${tx('THE PEOPLE MAKE THE PLACE','মানুষেই আপন ঠিকানা')}</p><h2 id="ch-people-title">${tx('Your kind of <em>company.</em>','আপনার <em>আপনজন।</em>')}</h2></div><a class="ch-text-link" href="#/community">${more('Meet everyone','সবার সাথে পরিচিত হোন')}</a></header><div class="ch-people-layout"><div class="ch-member-list">${members.map((m,i)=>`<a class="ch-person ch-person-${i}" href="#/members/${esc(m.id)}" data-reveal><span class="ch-avatar">${initials(m.name)}</span><div><div class="ch-person-title"><h3>${esc(m.name)}</h3>${m.isDemo?'<small>SAMPLE PROFILE</small>':''}</div><p>${esc(m.jobTitle||m.major||m.type)}${m.city?` · ${esc(m.city)}`:''}</p><div class="ch-person-tags">${(m.skills||[]).slice(0,2).map(skill=>`<span>${esc(skill)}</span>`).join('')}${m.mentor?'<span>Open to mentoring</span>':''}</div></div><span class="ch-person-arrow">${icon('arrowUp')}</span></a>`).join('')||'<p class="ch-empty">The directory is waiting for its first approved profile. Come introduce yourself.</p>'}<a class="ch-text-link culture-alumni-link" href="#/alumni">${more('Find an alumni mentor','অ্যালামনাই মেন্টর খুঁজুন')}</a></div><aside class="ch-noticeboard" aria-labelledby="ch-board-title"><div class="ch-board-pin" aria-hidden="true"></div><div class="ch-board-title"><div><p>FROM OUR LITTLE CORNER</p><h2 id="ch-board-title">${tx('The community board.','আমাদের নোটিশ বোর্ড।')}</h2></div><span lang="bn" aria-hidden="true">আড্ডা</span></div><div class="ch-board-tabs" role="group" aria-label="Noticeboard sections"><button type="button" data-home-board-filter="all" aria-pressed="true">All</button><button type="button" data-home-board-filter="notes" aria-pressed="false">Little notes</button><button type="button" data-home-board-filter="gatherings" aria-pressed="false">Meet-ups</button></div><div class="ch-board-items">
   ${previewNote?`<a class="ch-board-note" data-home-board-item="notes" href="#/community?wall=1"><small>${esc(postCategory[previewNote.category]||'Community note')} <span>LOCAL NOTE</span></small><p>${esc(previewNote.body)}</p><footer><b>${initials(previewNote.name)}</b><span>${esc(previewNote.name)}</span>${icon('arrowUp')}</footer></a>`:`<div class="ch-board-note" data-home-board-item="notes"><small>A CONVERSATION STARTER <span>YOUR VOICE HERE</span></small><p>“A little about me…”</p><button type="button" class="ch-text-link" data-community-action="post-compose" data-category="introduction">${more('Leave the first hello','প্রথম পরিচয় দিন')}</button></div>`}
   ${firstEvent?`<a class="ch-board-event" data-home-board-item="gatherings" href="#/events/${esc(firstEvent.slug)}"><span class="ch-mini-date"><b>${dateParts(firstEvent).day}</b>${dateParts(firstEvent).month}</span><div><small>${firstEvent.isDemo?'SAMPLE GATHERING':'COMMUNITY GATHERING'}</small><h3>${esc(firstEvent.title)}</h3><p>${esc(firstEvent.location)} · ${esc(firstEvent.time)} JST</p></div>${icon('arrowUp')}</a>`:`<div class="ch-board-event" data-home-board-item="gatherings"><div><small>GATHERINGS</small><h3>A little room in your calendar.</h3><p>New gatherings will appear here when announced.</p></div></div>`}
   </div><div class="ch-board-foot"><span>✽</span><p>Profiles and notes in this preview are saved on this device.</p><a href="#/community?wall=1" aria-label="Open the community wall">${icon('arrowUp')}</a></div></aside></div></section>
 <section class="ch-adda" id="community-wall" tabindex="-1" aria-labelledby="ch-adda-title"><div class="ch-section"><header class="ch-section-heading" data-reveal><div><p class="ch-eyebrow">02 / ${tx('PULL UP A CHAIR','চলুন, গল্প করি')}</p><h2 id="ch-adda-title">${tx('There’s always room<br>for <em>one more story.</em>','আরও একটি গল্পের জন্য<br><em>জায়গা আছে সবসময়।</em>')}</h2></div><a class="ch-text-link" href="#/community?wall=1">${more('All community notes','সব কথা')}</a></header><div class="ch-adda-grid"><div class="ch-adda-invitation" data-reveal><span class="ch-adda-bangla" lang="bn">আড্ডা হোক!</span><p>Found a great study spot? Settling into life in Japan? Missing your favourite fuchka? Start a conversation.</p><button type="button" class="btn ch-primary" data-community-action="post-compose">${more('Pin a little note','একটি কথা লিখুন')}</button><small>Interactive preview · Notes and replies stay in this browser.</small></div><div class="ch-home-notes">${posts.length?posts.map(p=>`<article class="ch-home-note" data-reveal><small>${esc(postCategory[p.category]||'Community note')}</small><p>${esc(p.body)}</p><footer><span><b>${initials(p.name)}</b>${esc(p.name)}</span><button type="button" class="ch-text-link" data-community-action="post-reply" data-id="${esc(p.id)}">Reply ↗</button></footer></article>`).join(''):`<div class="ch-first-note" data-reveal><span aria-hidden="true">✳</span><h3>The first story<br>could be yours.</h3><p>No notes here yet. Pick a conversation starter and make this corner a little more you.</p><div class="ch-starters"><button type="button" data-community-action="post-compose" data-category="introduction">A little about me… <span>Say hello ↗</span></button><button type="button" data-community-action="post-compose" data-category="question">Does anyone know… <span>Ask a question ↗</span></button><button type="button" data-community-action="post-compose" data-category="moment">Today felt like home… <span>Share a moment ↗</span></button></div></div>`}</div></div></div></section>
 <section class="rk-section rk-gatherings ch-gatherings" id="home-gatherings" tabindex="-1" aria-labelledby="rk-gatherings-title"><header class="ch-section-heading" data-reveal><div><p class="ch-eyebrow">03 / ${tx('MEET YOU THERE','দেখা হবে আয়োজনে')}</p><h2 id="rk-gatherings-title">${tx('Good company.<br><em>Even better memories.</em>','ভালো সঙ্গ।<br><em>রঙিন সব স্মৃতি।</em>')}</h2></div><a class="ch-text-link" href="#/events">${more('All gatherings','সব আয়োজন')}</a></header><div class="rk-event-grid">${events.map((e,i)=>`<article class="rk-event-ticket rk-ticket-${i}" data-reveal data-tilt><a class="rk-event-poster" href="#/events/${esc(e.slug)}"><img src="${esc(e.image)}" alt="${esc(e.title)} event artwork" loading="lazy"><span class="rk-event-category">${esc(e.category)}</span><span class="rk-event-open">${icon('arrowUp')}</span></a><div class="rk-event-ticket-body"><div class="rk-event-date"><span>${dateParts(e).month}</span><strong>${dateParts(e).day}</strong><small>${esc(e.date.slice(0,4))}</small></div><div class="rk-event-title">${e.isDemo?'<span class="rk-sample">SAMPLE GATHERING</span>':''}<h3><a href="#/events/${esc(e.slug)}">${esc(e.title)}</a></h3><p>${icon('pin')} ${esc(e.location)}</p><p>${icon('clock')} ${esc(e.time)} JST</p></div></div><div class="rk-ticket-stub"><span>${e.price?money(e.price):'Free entry'} ${e.foodEnabled?'· Food & friends':''}</span><a href="#/events/${esc(e.slug)}">Save your place ${icon('arrowUp')}</a></div></article>`).join('')||'<div class="empty-state">New gatherings will appear here.</div>'}</div>${events.some(e=>e.isDemo)?`<p class="rk-footnote">${icon('info')} Sample gatherings let you try registration. Official events will be announced by TIU BSS.</p>`:''}</section>
 <div id="home-reels" tabindex="-1">${renderReelSections(ctx,tx,{compact:true})}</div>
 <div id="home-mela" tabindex="-1"><section class="ch-ride-band" aria-labelledby="ch-ride-title"><div class="ch-ride-copy" data-reveal><p class="ch-eyebrow">05 / A COLOURFUL LITTLE DETOUR</p><h2 id="ch-ride-title">${tx('Your ride to<br><em>the celebration.</em>','চলুন যাই<br><em>রঙের উৎসবে।</em>')}</h2><p>${tx('Our painted rickshaw has a new stop. Come for the food, make a little art, and stay for the people.','আমাদের রঙিন রিকশার নতুন গন্তব্য। ঘরের খাবার, নিজের শিল্প আর প্রিয় মানুষের সাথে আড্ডা।')}</p><button class="ch-text-link" type="button" data-home-jump="digital-mela">${more('Hop on. Let’s wander.','চলুন, মেলা ঘুরে দেখি।')}</button></div><div class="ch-ride-stage">${renderRickshawStage(ctx,tx)}</div></section>${renderMela(ctx,tx,true)}</div>
 ${renderCultureTrail(ctx,tx)}
 <section class="rk-gallery-section ch-gallery" aria-labelledby="ch-gallery-title"><header class="ch-section-heading" data-reveal><div><p class="ch-eyebrow">COLOUR FROM HOME / ঘরের রং</p><h2 id="ch-gallery-title">${tx('A little art.<br><em>A lot of belonging.</em>','রঙিন শিল্পে<br><em>আপন অনুভূতি।</em>')}</h2></div><a class="ch-text-link" href="#/gallery">${more('Open the artwork gallery','শিল্পের গ্যালারি দেখুন')}</a></header><div class="rk-artwall">${gallery.map((g,i)=>`<button class="rk-artprint rk-artprint-${i}" data-global="gallery" data-id="${esc(g.id)}" data-reveal aria-label="View ${esc(g.title)}"><div class="rk-artprint-image"><img src="${esc(g.image)}" alt="${esc(g.caption||g.title)}" loading="lazy"><span>${icon('arrowUp')}</span></div><div class="rk-artprint-caption"><small>0${i+1} / ${esc(g.category)}</small><h3>${esc(g.title)}</h3></div></button>`).join('')}</div><p class="rk-footnote">Artwork references & original illustrations. Community photographs can be added from the admin workspace.</p></section>
 <section class="ch-final"><img src="assets/rickshaw-bird.svg" width="120" height="120" alt="" aria-hidden="true" data-float><div><p class="ch-eyebrow">COME AS YOU ARE. BELONG AS YOU ARE.</p><h2>${tx('The best part is <em>you.</em>','আপনিই আমাদের <em>আপনজন।</em>')}</h2><p>Student. Alumnus. Friend. There’s a place for your story here.</p></div><a class="btn ch-primary" href="#/join">${more('Come be part of it','আমাদের সঙ্গী হোন')}</a></section>
 </div>`;
}

export function mountCommunityHome(){
 const home=document.querySelector('.ch-home');if(!home)return;
 home.querySelectorAll('[data-home-jump]').forEach(button=>button.addEventListener('click',()=>{
  const target=document.getElementById(button.dataset.homeJump);if(!target)return;
  const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
  target.scrollIntoView?.({block:'start',behavior:!reduce&&document.documentElement.dataset.motion==='on'?'smooth':'auto'});
  if(!target.hasAttribute('tabindex'))target.setAttribute('tabindex','-1');
  target.focus?.({preventScroll:true});
 }));
 home.querySelectorAll('[data-home-board-filter]').forEach(button=>button.addEventListener('click',()=>{
  const filter=button.dataset.homeBoardFilter;
  home.querySelectorAll('[data-home-board-filter]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));
  home.querySelectorAll('[data-home-board-item]').forEach(item=>{item.hidden=filter!=='all'&&item.dataset.homeBoardItem!==filter;});
 }));
}
